    """Roll a prepared, interrupted commit forward or back.

    Invoked only from the write path (never :meth:`recover`, which is
    strictly read-only). A staged intent proves exactly which
    transaction was in flight, so either outcome is deterministic:

    * the database already holds the prepared state -- publish the
      prepared anchor link (roll-forward);
    * the database still matches the current anchor -- the
      transaction never committed; discard the intent (rollback).
    """
    if self._in_memory or self._intent_path is None:
        return
    try:
        intent = _load_intent(self._intent_path, anchor.key)
    except _AnchorCorrupt:
        raise RuntimeError("integrity anchor is incomplete") from None
    if intent is None:
        return
    seq, pred, state_hash = intent
    if anchor.seq + 1 != seq or not hmac.compare_digest(anchor.head, pred):
        raise RuntimeError("integrity anchor is invalid")
    current_hash = _canonical_state_hash(conn)
    prepared_head = _link_digest(anchor.key, seq, pred, state_hash)
    if hmac.compare_digest(current_hash, state_hash):
        # SQLite committed before the crash; finish the anchor phase.
        document = {
            "version": _ANCHOR_VERSION,
            "key": base64.b64encode(anchor.key).decode("ascii"),
            "seq": seq,
            "pred": pred,
            "head": prepared_head,
