    # sidecar swapped for another database's anchor file.
    if self._anchor is not None and not hmac.compare_digest(
        anchor.key, self._anchor.key
    ):
        return "invalid"

    try:
        intent = _load_intent(intent_path, anchor.key)
    except _AnchorCorrupt:
        return "incomplete"

    state_hash = _canonical_state_hash(conn)
    head_digest = _link_digest(
        anchor.key, anchor.seq, anchor.pred, state_hash
    )
    anchor_matches = hmac.compare_digest(head_digest, anchor.head)

    if intent is None:
        return "valid" if anchor_matches else "invalid"

    seq, pred, prepared_state = intent
    prepared_committed = hmac.compare_digest(state_hash, prepared_state)
    intent_extends_anchor = anchor.seq + 1 == seq and hmac.compare_digest(
        anchor.head, pred
    )

    if anchor_matches:
        # Crash after the anchor landed but before intent cleanup:
        # the committed state is fully anchored.
        return "valid"
    if not intent_extends_anchor:
        # The staged intent does not continue the recorded chain.

    try:
        intent = _load_intent(intent_path, anchor.key)
    except _AnchorCorrupt:
        return "incomplete"

    state_hash = _canonical_state_hash(conn)
    head_digest = _link_digest(
        anchor.key, anchor.seq, anchor.pred, state_hash
    )
    anchor_matches = hmac.compare_digest(head_digest, anchor.head)

    if intent is None:
        return "valid" if anchor_matches else "invalid"

    seq, pred, prepared_state = intent
    prepared_committed = hmac.compare_digest(state_hash, prepared_state)
    intent_extends_anchor = anchor.seq + 1 == seq and hmac.compare_digest(
        anchor.head, pred
    )

    if anchor_matches:
        # Crash after the anchor landed but before intent cleanup:
        # the committed state is fully anchored.
        return "valid"
    if not intent_extends_anchor:
        # The staged intent does not continue the recorded chain.
        return "incomplete"
    if prepared_committed:
        # SQLite committed the prepared state but the anchor was not
        # replaced: an interrupted, recoverable commit.
        return "incomplete"
    # The prepared transaction did not commit. This is only coherent
    # when SQLite still holds exactly the last anchored state; any
    # other state means the database diverged from both stores.
    anchored_state_head = _link_digest(
        anchor.key, anchor.seq, anchor.pred, state_hash
    )
    if hmac.compare_digest(anchored_state_head, anchor.head):
        return "incomplete"
    return "invalid"

